def transform(grid):
    h, w = len(grid), len(grid[0])
    directions = [
        (0, 1, lambda r, c: r),
        (1, 0, lambda r, c: c),
        (1, 1, lambda r, c: r - c),
        (1, -1, lambda r, c: r + c),
    ]

    best = None
    best_score = -1
    for dr, dc, invariant in directions:
        score = 0
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                rr, cc = r + dr, c + dc
                if color and 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    score += 1
        if score > best_score:
            best_score = score
            best = (dr, dc, invariant)

    _, _, invariant = best
    tracks = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                tracks[invariant(r, c)] = color

    period = len(tracks)
    pattern = {key % period: color for key, color in tracks.items()}
    return [
        [pattern[invariant(r, c) % period] for c in range(w)]
        for r in range(h)
    ]
